INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('81ec5a41-0648-4bad-947e-88e74e05e0c3', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "f896a0a3-6039-42e6-9085-8ee9469e295b", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "a655033a-3ddc-4d58-a295-3cacdfc07d24", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "d6588273-bcbb-400e-83d4-0bf528356675", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "438af8b7-97ec-4a71-bb43-089ddb0b0803", "text": "Ha a területük 0", "isCorrect": false}, {"id": "3cafc237-f273-4fee-b523-5a7b1dc6719f", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "3340dee5-164f-4b54-9960-9bf8671b5de8", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "fa320562-df0b-4ff5-bd97-be6139ddb602", "text": "Igaz", "isCorrect": true}, {"id": "c90a2a1c-3022-4d99-8314-39ca3dda5828", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "88218c39-7cce-4587-ab5f-d628855de166", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "1bb0d427-1756-46c6-bff8-b82de173d96f", "text": "Igaz", "isCorrect": true}, {"id": "aca27053-8040-426c-9c7e-eca5f69b03a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "740110f8-3967-488c-8d37-233d7d8bfa22", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "6212acd1-334d-45a7-9c6e-b899063956b7", "text": "Igaz", "isCorrect": false}, {"id": "10bc04bb-fd8b-4995-9ad8-728b70fcd178", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "b4c6700b-5397-4c87-8a98-d101db0a27b2", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "eb79f5a1-a953-4b03-b888-800b6fec5b2c", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "7dc9b9a8-1933-44d0-9493-dd1e3d69687f", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "4d60d87c-3e15-4e87-afea-e9b6a66853fc", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "86ac8b25-ddc3-4bf7-8ee8-d5a3d7acc18a", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "a734bfc9-a442-47e0-b491-5b1a27cb75bf", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "5919c96e-926d-4165-9634-ffcc50400640", "text": "Igaz", "isCorrect": false}, {"id": "9cea3475-40e9-4649-abc2-0b9af4134e73", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "114c7502-dea3-49e5-9174-b37bceece93a", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "2e420198-544a-4103-8d03-96d4ea5d5ea5", "text": "Igaz", "isCorrect": true}, {"id": "f8d036e9-88f7-48d5-81d2-c73394db3480", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5ebadacb-fc01-4e7c-b1fe-90fb57e34853', '21feff02-016d-46e2-bb9d-c27495133b1b', '51. óra: A kör', 'A kör elemei: középpont (O), sugár (r), átmérő (d), húr, körív, körző használata.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "15ef336d-df40-4286-82d5-874a1892af56", "text": "Hogyan viszonylik a kör átmérője (d) a sugárhoz (r)?", "type": "multiple-choice", "options": [{"id": "c21a5a18-e1c2-4787-bc8f-a31a5ee901a2", "text": "d = 2 * r (az átmérő a sugár kétszerese)", "isCorrect": true}, {"id": "ed9583d2-a27d-46e8-85aa-4528b91f1739", "text": "d = r / 2", "isCorrect": false}, {"id": "8e66881c-0730-4206-9e65-cfb50b54561b", "text": "d = r + 5", "isCorrect": false}, {"id": "6a906d2d-42ea-4199-9015-4ebeb861f09d", "text": "d = r * r", "isCorrect": false}], "timeLimit": 15}, {"id": "53717776-796f-4252-a9e2-6410311e8fa1", "text": "Ha a kör sugara r = 5 cm, mennyi az átmérője (d)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "9666757e-c555-476c-8f7d-ddd62b50bc1d", "text": "Ha a kör átmérője d = 16 cm, mennyi a sugara (r)? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "6f564c61-a682-40c8-ae04-cd972c902b8c", "text": "A körvonal pontjai a középponttól egyenlő távolságra (sugárnyira) vannak.", "type": "true-false", "options": [{"id": "5152f6d5-da45-4202-a9b2-6f3e38d7fed3", "text": "Igaz", "isCorrect": true}, {"id": "86ced08a-d3f9-450d-992d-4fb273f76cb0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0d7106f0-e956-4698-a03f-35be5642dd85", "text": "Mi a kör leghosszabb húrja?", "type": "multiple-choice", "options": [{"id": "bc7c9642-c446-4586-9493-045e429910e3", "text": "Az átmérő", "isCorrect": true}, {"id": "f61fa82c-1d12-42f3-b1af-d4ce89be4ab4", "text": "A sugár", "isCorrect": false}, {"id": "2ea7b793-7dd8-4ee3-ab3a-771d84456b2c", "text": "A körív", "isCorrect": false}, {"id": "e0fd4a28-bbb5-4af8-96cd-0318341255d5", "text": "A körcikk", "isCorrect": false}], "timeLimit": 15}, {"id": "9e521424-ca5f-4123-8242-b0b524b363d2", "text": "A körző a körök rajzolására és távolságok másolására szolgáló szerkesztőeszköz.", "type": "true-false", "options": [{"id": "0a0d20c9-85ea-4f64-87de-3bdc4f7a0865", "text": "Igaz", "isCorrect": true}, {"id": "a90684d9-7810-41ef-8a0d-a73a4c3889b2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8361eae2-26bd-4dee-8ba3-b96b3ec6270f", "text": "A kör belsejében lévő pontok távolsága a középponttól kisebb, mint a sugár.", "type": "true-false", "options": [{"id": "c14b4167-3f6a-4997-b82b-38281134b0a3", "text": "Igaz", "isCorrect": true}, {"id": "3f7e706e-ee72-4bd5-86e8-a1fa9cd35e9f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bba07cf6-7db5-4b07-b5b9-d83e42a0d324', '21feff02-016d-46e2-bb9d-c27495133b1b', '52. óra: A szakasz felezőmerőlegese', 'A szakaszfelező merőleges tulajdonságai, szerkesztése körzővel és vonalzóval.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "8ed73538-8768-4d1f-bad7-12ffa6e03237", "text": "Mi a szakaszfelező merőleges egyenes fő tulajdonsága?", "type": "multiple-choice", "options": [{"id": "c3512051-65c5-4b8f-8053-1702f7e16e8a", "text": "A szakasz felezőpontján áthaladó, a szakaszra merőleges egyenes, melynek pontjai egyenlő távolságra vannak a szakasz két végpontjától", "isCorrect": true}, {"id": "33e58f20-f157-4826-851d-ecccf31b89ab", "text": "A szakasszal párhuzamos egyenes", "isCorrect": false}, {"id": "12b6210a-8c72-4d8d-bc5c-e767c52c0585", "text": "A szakasz egyik végpontján átmenő egyenes", "isCorrect": false}, {"id": "2c369828-a712-45a6-8b2a-747b88fb3d7a", "text": "Minden szakaszhoz 2 felezőmerőleges tartozik", "isCorrect": false}], "timeLimit": 15}, {"id": "d7bc9ccf-f9e4-4f9b-a549-e7d05ecf2d54", "text": "Hány felezőmerőlegese van egy szakasznak a síkban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "239ae8ac-074f-46a9-a2ec-34aa86baf8ce", "text": "A szakaszfelező merőleges egyenes pontjai egyenlő távolságra vannak a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "7ee72baa-10a0-4bf8-b7a9-9dfad6552d89", "text": "Igaz", "isCorrect": true}, {"id": "8dda34ae-6191-4d79-a8b9-cff276634a79", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e585ce02-7f42-461b-b36f-5c48ad787983", "text": "A szakasz felezőmerőlegesének megszerkesztéséhez a szakasz felénél nagyobb körzőnyílás szükséges.", "type": "true-false", "options": [{"id": "c1ae7a1f-9a5e-4639-9172-7560c2aedc44", "text": "Igaz", "isCorrect": true}, {"id": "f3b156ec-8a20-48a7-8270-93565aaaee01", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7ebafc2e-25f3-4d1d-90de-08834a68dbf1", "text": "Hány fokos szöget zár be a felezőmerőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "03f5c064-01fb-40d8-907c-e042f0cac71b", "text": "A háromszög oldalfelező merőlegesei egy pontban metszik egymást (a körülírt kör középpontjában).", "type": "true-false", "options": [{"id": "4e452661-be94-4b99-a427-d0449f6d6d67", "text": "Igaz", "isCorrect": true}, {"id": "a7e4670c-66e1-4155-b37e-63b3a85fe147", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d529c0d-b6db-465b-b0f6-f361d5df8843", "text": "Egy 8 cm-es szakasz felezőpontja a végponttól 4 cm-re van.", "type": "true-false", "options": [{"id": "47281b94-7214-4a85-8231-647f76c21acc", "text": "Igaz", "isCorrect": true}, {"id": "5c395717-f3ed-4785-aac8-fa586656346d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ed575cf5-a573-4e5e-a09a-2c0b4ffe9da2', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "8d9aeba2-8254-4e9c-9f7d-a1532da76a9f", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "5f8bc07a-ba59-4d69-889a-b69b6db0d4b9", "text": "Körzőt", "isCorrect": true}, {"id": "34e46505-dbe0-4528-92b2-d43ed807e40f", "text": "Szögmérőt", "isCorrect": false}, {"id": "655cbd73-4a5c-484b-ab8c-94024551a762", "text": "Radírt", "isCorrect": false}, {"id": "a284e666-d4af-4a77-94ba-37f75e72843e", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "9d02d6f0-5bca-4ad2-b1c3-1b70ca5204ea", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "bf747045-43b1-4e4d-9749-82fb25cf995c", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "e7603b54-63bd-4b77-b996-f05e7a197414", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "a59e7fda-dd3e-4441-a07e-182ed777a69f", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "a3a625ca-b331-4196-8f0d-c8b7b17882d7", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "fb074c5d-68b3-45ad-9933-644794c2868a", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "c67f374a-3571-4470-944c-794827443df8", "text": "Igaz", "isCorrect": true}, {"id": "c4e7129f-b95c-46d4-8b62-e1040f555b5e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a0b98863-ace7-45f1-a0d8-56b2ddfe4814", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "8ff25ede-539c-4f80-a27e-c0720e04d0ac", "text": "Igaz", "isCorrect": true}, {"id": "1f80165a-02e1-460f-afb6-99bb80dccf5c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f7938217-eef7-4f62-98a8-dd35caa5f167", "text": "Hány fokos szöget zár be két egymásra merőleges egyenes?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "a020d90b-be32-4f8b-88dd-78458dd9c120", "text": "Két párhuzamos egyenes sehol sem metszi egymást a síkban.", "type": "true-false", "options": [{"id": "e48b2936-4a13-46bd-bc27-3fa16cba48db", "text": "Igaz", "isCorrect": true}, {"id": "66852867-8483-495b-a10c-5343c0e486cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "17494622-a263-4406-baae-a55ad21e7b40", "text": "A pontos és esztétikus szerkesztés alapkövetelmény a geometriában.", "type": "true-false", "options": [{"id": "deb9990c-98c3-45e6-8792-1474c43315fd", "text": "Igaz", "isCorrect": true}, {"id": "9a7a22ec-2c6b-48c9-8b75-a28f2d006426", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1c1e8977-25a5-4cf4-ad21-8c60a34cc266', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "7c6e2952-3117-4fb4-96ab-8d68455628d6", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "8c0d78b1-8aa3-49b7-b404-726d9f7918fb", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "7bae6fc9-7305-4c4a-aded-9340e66d7227", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "e51e379e-2380-4518-9ab3-0ff3585306aa", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "ca715534-65c2-4c92-816c-bc552824a0b0", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "f2968406-1ca9-4086-ba5c-c8c806d7629c", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "6233c420-c4de-48e8-9d9c-6aff6fb64807", "text": "Igaz", "isCorrect": false}, {"id": "df5a239e-dadf-465e-99be-19d8ca9302be", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "4b9b7058-fb2c-4076-8ee0-4bb7032bb900", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "381fe626-d671-408a-a33d-4dcd4207f733", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "bb3e8f78-1348-417a-aa9f-bb64a3d81cca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f6a632ab-985e-4f09-b5fa-6b8a99cfa2b7", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "96daa9ac-41db-4edc-b7f3-521b31ab5b8e", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "419616d4-0c35-411a-9ddd-e7fdc714c56a", "text": "Igaz", "isCorrect": true}, {"id": "af562a76-4d8e-4d65-8383-9d779a4fe937", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2460bd03-3eb8-4c8d-b4c1-dbd507c5a7cf", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "4e7f52bd-9a14-461d-b9d1-a9e1bd311cd9", "text": "Igaz", "isCorrect": false}, {"id": "60b27833-5a13-47fa-a28c-a916fe21e173", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "44662858-c549-497b-b954-ce3f5b20d862", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "1b6d7a37-71e8-40e2-94fe-ad6e5753b1c6", "text": "Igaz", "isCorrect": true}, {"id": "0c98904d-1ca2-4775-b69a-08bcc0ba7cf9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('da12e9b9-8650-4bd8-ae3b-9210d8930897', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "4bfffb5f-0508-46cf-8961-fe81379da269", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "810745a4-8ea4-44cc-b1c7-f4d06e23a8f6", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "92452b57-3d39-4f13-96e6-79e62cb503f0", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "90009558-a7fa-42e1-9d8d-c1b1863f66ab", "text": "Igaz", "isCorrect": false}, {"id": "9099300f-a551-4c42-a853-529c075481d0", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "e39fa5d8-6758-4341-ac88-fb659f98e7cd", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "747b6139-1e24-428b-8f84-460971740b79", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "338a5bab-fa43-43ae-9bc8-9a3b5b2f5f9c", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "1f9c068b-21d3-447e-9cb1-7d20660d919b", "text": "Igaz", "isCorrect": true}, {"id": "2d594675-84de-4ff7-b748-8d52da9b8824", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5ebb96d7-8cb3-4d9b-8124-e5408497655e", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "6ebfa9f8-6bfc-4902-aa4a-ad8c260abc0c", "text": "Tompaszög", "isCorrect": true}, {"id": "35df6e0a-4ff5-4697-a6ac-9c0a701a866b", "text": "Hegyesszög", "isCorrect": false}, {"id": "036fa0ed-59e5-4b05-bc8c-0c7047321b0d", "text": "Derékszög", "isCorrect": false}, {"id": "b47f08f2-8596-4311-9209-f362da5f5784", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "fd904dbd-55ca-48e1-9670-1e2cf85137c1", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e271d8ad-3778-4a39-a705-9f0d0f48443e", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "a20a2f7d-81d6-4605-9900-24613a59c18c", "text": "Igaz", "isCorrect": true}, {"id": "eb0103af-2b6b-420a-b0f8-e93e72f6f4b7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e648023-145e-4f6b-94fd-5e4fabf1fa29", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('be379ccd-9b0f-4159-b536-d56832a265b3', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "faecf80c-bd7e-49d5-9138-a54c388e815e", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "c43c710a-c241-4b98-aaaa-a32866034c8e", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "1a3ea4bf-1f33-4372-ae9d-d62d96826157", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "9542f4c6-5068-4b99-8c11-cc6d11b20ad4", "text": "7 négyzet", "isCorrect": false}, {"id": "796eb6c9-7358-4f96-b7ed-182f05bef9e6", "text": "7 kör", "isCorrect": false}, {"id": "08c53a60-9cb6-4346-9484-301b665e8f1e", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "e8e0db94-3b01-4eb4-9339-8932a383f9f1", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "d74caff9-96a3-4966-8b4b-b6d208632366", "text": "Igaz", "isCorrect": true}, {"id": "e3baa337-ff99-4a06-b544-b4e62fa766b8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "32f478fd-ef7e-4fc4-86f9-ffb358b459b0", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "a94d1616-3319-4e60-8ba2-8a92cd5e47cc", "text": "Igaz", "isCorrect": true}, {"id": "d780ebe1-ca33-47d8-9e8a-bb89b01db18b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bdf598e-c2ee-4f0f-b6f4-0c82d8c9ea07", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "28b16e29-f209-4334-98f3-f731b7a61b2c", "text": "Igaz", "isCorrect": true}, {"id": "9f36429b-199a-4896-bfe0-e0ddff1cfc3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "86e35841-bcfa-40da-84dc-82336a32f6c5", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "9ec431dc-8e80-4f9f-b1b5-bfc3b43d6de4", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "53b4407b-1bc5-425b-9abe-a89b635b6498", "text": "Igaz", "isCorrect": true}, {"id": "0cbc26c5-5f56-41d0-ba4a-1e5aec524e19", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('18ab47be-0411-4238-9dac-4f33a36b4883', '21feff02-016d-46e2-bb9d-c27495133b1b', '57. óra: Tengelyes tükrözés', 'Tengelyes tükrözés fogalma, tengely (t), tárgy és tükörkép (A és A'').', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "0827128b-f751-4894-aca4-342190437d56", "text": "Mi a tengelyes tükrözés lényege egy ''t'' tengelyre nézve?", "type": "multiple-choice", "options": [{"id": "0617b935-c036-453e-95ec-f70c61509037", "text": "A pont és tükörképe a tengelyre merőleges egyenesen van, és egyenlő távolságra van a tengelytől", "isCorrect": true}, {"id": "d38f19e8-f12b-4f3d-83f7-44e331aaf838", "text": "A pontot eltoljuk párhuzamosan", "isCorrect": false}, {"id": "39c192a7-8c85-47e5-b1b5-b460a8d91fc0", "text": "A pontot elforgatjuk 180 fokkal", "isCorrect": false}, {"id": "fe9ac07a-296c-4ce4-91e5-d37069520d15", "text": "A pontot lefelé mozgatjuk 5 cm-rel", "isCorrect": false}], "timeLimit": 15}, {"id": "3fefb9e5-bbc7-4890-9c60-3bcd3f04f5bd", "text": "Hol van a tengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "e9dc83cf-6941-4a28-8887-e560cbec88be", "text": "Önmagában (fixpont)", "isCorrect": true}, {"id": "769c4c77-8433-4187-9585-c8dec978fb99", "text": "Az origóban", "isCorrect": false}, {"id": "50ed5666-48f1-4e47-8683-ddf6275eb19d", "text": "Végtelenben", "isCorrect": false}, {"id": "038354b7-d479-4f93-b24a-a94f3d38ffbe", "text": "A tengely másik végén", "isCorrect": false}], "timeLimit": 15}, {"id": "63193d02-67eb-4280-ab87-45f9b3125960", "text": "Ha a P pont 4 cm-re van a tükörtengelytől, milyen messze van a P'' tükörkép a tengelytől?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b77c622d-e865-4be5-add8-4fdbca139373", "text": "Milyen messze van a P pont a P'' tükörképétől, ha a tengelytől való távolsága 4 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b8ffea3a-0bf5-44c9-9b9f-bf7b2103653e", "text": "A tengelyes tükrözés egybevágósági transzformáció.", "type": "true-false", "options": [{"id": "f1128871-cdf4-4fba-97d1-8846ed8d3d38", "text": "Igaz", "isCorrect": true}, {"id": "78de8bd1-147b-458d-b7bb-481c575af652", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc36e253-7bc6-4f34-b24f-ce9096df16fd", "text": "A tengelyes tükrözés megváltoztatja az alakzat körüljárási irányát (pl. óramutató járásával megegyezőből ellentétes lesz).", "type": "true-false", "options": [{"id": "dc7c8e09-627d-4452-ad65-7a410895bb44", "text": "Igaz", "isCorrect": true}, {"id": "5fc5ad38-ba06-47c8-8185-706b029aa336", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "93b6ce1c-4ecc-42b9-a115-2d2fad8f3942", "text": "A tengelyesen tükrös alakzat és tükörképe egybevágó.", "type": "true-false", "options": [{"id": "5a12ca73-fd7a-4307-9ec5-e6adceb91d6e", "text": "Igaz", "isCorrect": true}, {"id": "74870eda-a03d-41e0-a36c-b98c6d44a306", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f803d1e4-7d63-4579-b046-bb19eeef2726', '21feff02-016d-46e2-bb9d-c27495133b1b', '58. óra: A tengelyes tükrözés tulajdonságai', 'Távolságtartás, szögtartás, körüljárási irány megváltozása, egyenes és kör tükörképe.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "0a083aa2-8372-458c-bf36-ffcf6a7d88df", "text": "Melyik tulajdonság érvényes a tengelyes tükrözésre?", "type": "multiple-choice", "options": [{"id": "22b851b3-0468-4184-9437-3bf837de7ef1", "text": "Távolságtartó, szögtartó, egyenestartó és megváltoztatja a körüljárási irányt", "isCorrect": true}, {"id": "552ec298-5b29-4225-bf7d-9ae22ee4b690", "text": "Növeli a szakaszok hosszát", "isCorrect": false}, {"id": "244baec1-57c6-42e2-942f-aa5590783ea5", "text": "Megváltoztatja a szögek nagyságát", "isCorrect": false}, {"id": "984309dd-b3c5-4992-8740-8299530a9bac", "text": "Négyszögből háromszöget csinál", "isCorrect": false}], "timeLimit": 15}, {"id": "22f9d131-72a9-4cba-b6e7-d71690a2049d", "text": "Egy 5 cm-es szakasz tengelyes tükörképe is 5 cm hosszú.", "type": "true-false", "options": [{"id": "746b4ed0-393d-4a87-ab23-59391dd47207", "text": "Igaz (távolságtartó)", "isCorrect": true}, {"id": "0e623675-c4be-40c4-b099-adb8f3fc51b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec9031b5-2e18-44b6-a98a-1ae33e1c7389", "text": "Egy 45°-os szög tengelyes tükörképe is 45°-os.", "type": "true-false", "options": [{"id": "8f9bbcad-dfc6-4aa6-8018-c00ebe25ae93", "text": "Igaz (szögtartó)", "isCorrect": true}, {"id": "83205d76-735d-42d4-a787-058b02a00abf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b33091f-e04b-41c4-9d5c-6de47b06b602", "text": "A tengelyre merőleges egyenes tükörképe önmaga (önmagába transzformálódik).", "type": "true-false", "options": [{"id": "a5518f37-81d8-4fc6-baf9-db617cfcf1ac", "text": "Igaz", "isCorrect": true}, {"id": "c34d347f-1daf-48af-85a7-e45a9b46537d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "edd90e05-c829-4afa-8a77-4176e475642c", "text": "Egy kör tengelyes tükörképe ugyanolyan sugarú kör.", "type": "true-false", "options": [{"id": "6f823e1b-837d-4d53-8879-006de3ac1e0b", "text": "Igaz", "isCorrect": true}, {"id": "78fc1ff6-cdc3-4b37-b62e-40d36b003e51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8ec4d28-72ff-4005-8365-c7469aa5c64c", "text": "A tengellyel párhuzamos egyenes tükörképe is párhuzamos a tengellyel.", "type": "true-false", "options": [{"id": "ba57f61c-9f1d-488a-a15c-b13d18508836", "text": "Igaz", "isCorrect": true}, {"id": "4bae6cb1-4b0b-4f83-afae-e3a27aeae09e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "01e35fa4-a85e-4816-9d14-4448d4b8c516", "text": "Hány fixpontja (helyben maradó pontja) van a tengelyes tükrözésnek a síkban?", "type": "multiple-choice", "options": [{"id": "6c771293-bc76-4989-8097-14d607ab47b7", "text": "Végtelen sok (a tükörtengely minden pontja)", "isCorrect": true}, {"id": "8d8f66b7-0be6-4c7a-ae40-58bd8415a691", "text": "Csak 1", "isCorrect": false}, {"id": "8ea255ca-6bba-4ded-af0e-d6ca43d7f2fb", "text": "Nincs egy sem", "isCorrect": false}, {"id": "de0ae8a9-8e9c-4f73-b18a-cabf705179b6", "text": "Pontosan 2", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6f559bff-6cf3-4ea5-b27d-2edbaa064922', '21feff02-016d-46e2-bb9d-c27495133b1b', '59. óra: Gyakorlóóra', 'Tengelyes tükörkép szerkesztésének gyakorlása pontok, szakaszok, sokszögek esetén.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d6686ad8-4de5-4f3f-8998-7d36f9798abc", "text": "Hogyan szerkesztjük meg egy P pont ''t'' tengelyre vonatkozó tükörképét?", "type": "multiple-choice", "options": [{"id": "a3b12817-9879-433e-a11c-432ad4edabd0", "text": "Merőlegest állítunk P-ből ''t''-re, és a talpponttól felmérjük a P távolságát a merőlegesre", "isCorrect": true}, {"id": "12d0f623-2945-4234-baa6-4d7ff9063a69", "text": "Párhuzamost húzunk ''t''-vel", "isCorrect": false}, {"id": "3246a9bb-3d8a-4213-a14d-8caa34647034", "text": "Körzővel kört rajzolunk P középponttal", "isCorrect": false}, {"id": "3aa7565d-c7be-46b4-a464-f675810d2b91", "text": "Összekötjük P-t az origóval", "isCorrect": false}], "timeLimit": 15}, {"id": "1015f95f-0dd2-47d3-aae7-2fa8c9eb3c34", "text": "Egy háromszög tengelyes tükrözése után a kapott háromszög területe megegyezik az eredetivel.", "type": "true-false", "options": [{"id": "bc4d1597-9f88-451c-ba3f-8bc01d606b42", "text": "Igaz", "isCorrect": true}, {"id": "39518b47-0191-463d-8abe-ffa81994c65b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "af23da09-dd67-434c-87da-57ac288a32b5", "text": "Ha a P pont a tengelyen van, hol van a tükörképe?", "type": "multiple-choice", "options": [{"id": "2eb032c5-2faf-4ec4-9829-1cf711cdbbf3", "text": "Önmagában (P = P'')", "isCorrect": true}, {"id": "0d9e9655-a2b4-403d-a469-2f6cc18045df", "text": "A tengely másik oldalán", "isCorrect": false}, {"id": "d34aa1a9-8fc5-4c3b-93ce-08f446a3ea41", "text": "A sík szélén", "isCorrect": false}, {"id": "0c4e42f8-ad23-4893-9bb3-9a7ed20aaefd", "text": "Az origóban", "isCorrect": false}], "timeLimit": 15}, {"id": "a3ac2e02-9957-45b2-b390-8514b4be13b5", "text": "A szakasz felezőmerőlegese a szakaszt önmagára tükrözi vissza.", "type": "true-false", "options": [{"id": "3d76f9d1-30dc-4aec-a5be-dcca892f16f7", "text": "Igaz", "isCorrect": true}, {"id": "4711f2d9-058e-473e-8cfa-7dcc1753466e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "beb72790-04e5-4c5b-a21d-ef76e9dc4781", "text": "Melyik betűnek VAN függőleges szimmetriatengelye? (pl. A, M, Y, W)", "type": "multiple-choice", "options": [{"id": "10115fa6-9f56-42e0-b36f-41440e804803", "text": "A", "isCorrect": true}, {"id": "2236ac13-bf55-4310-b18b-b40e7b833045", "text": "F", "isCorrect": false}, {"id": "8f566e0b-c328-4c53-9807-8d2cf886f352", "text": "L", "isCorrect": false}, {"id": "d25497c4-0ac5-439b-a60b-6f93346c3e6e", "text": "R", "isCorrect": false}], "timeLimit": 15}, {"id": "36969fa6-075d-48f4-aab7-71abe35eedcb", "text": "Melyik betűnek VAN vízszintes szimmetriatengelye? (pl. B, C, D, E, K)", "type": "multiple-choice", "options": [{"id": "e5f55b79-b41b-43e3-b702-ba72cc68d2b4", "text": "E", "isCorrect": true}, {"id": "0216be82-3a23-479e-ae25-ab62ca0ce0dc", "text": "F", "isCorrect": false}, {"id": "58f7d6ba-6435-4f94-af11-a1f042f22abc", "text": "G", "isCorrect": false}, {"id": "cfd2c9df-fa23-4640-b3d6-8ffc3fc56766", "text": "J", "isCorrect": false}], "timeLimit": 15}, {"id": "8aecfd71-df60-4cb1-9203-33546c8e900b", "text": "A tengelyesen tükrös alakzatok szimmetrikusak a tükörtengelyre.", "type": "true-false", "options": [{"id": "0dc9afa0-0a3c-4dac-8e67-d200b0a60ac5", "text": "Igaz", "isCorrect": true}, {"id": "a2320163-4bd7-4874-8417-222b39ea8790", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());